insert into blog_posts (slug,title_ar,excerpt_ar,category,status,seo_title,seo_description) values
('paper-weights-guide','دليل أوزان الورق: كيف تختار الوزن المناسب لكل مطبوعة؟','من الكروت الشخصية إلى الكتب والبروشورات، الوزن يغيّر الإحساس والتكلفة وطريقة التشطيب.','الطباعة الورقية','draft','دليل أوزان الورق للطباعة','شرح عملي لاختيار وزن الورق المناسب للكروت والبروشورات والكتب والمطبوعات التجارية.'),
('cmyk-vs-rgb','CMYK أم RGB؟ ما الذي يجب أن تعرفه قبل إرسال ملفك للطباعة','شرح عملي يمنع اختلاف الألوان والمفاجآت بين الشاشة والمنتج النهائي.','تجهيز الملفات','draft','CMYK وRGB للطباعة','الفرق بين أنظمة الألوان وكيفية تجهيز الملفات للطباعة.'),
('calendar-2027-marketing','كيف تحوّل تقويم 2027 إلى أداة تسويق تعيش عامًا كاملًا؟','اختيار الشكل والمحتوى والتوزيع الذي يجعل التقويم مساحة إعلان يومية.','أفكار تسويقية','draft','تقاويم 2027 للشركات','أفكار تصميم وطباعة تقاويم 2027 للشركات والمؤسسات.'),
('corporate-anniversary-magazine','مجلة ذكرى تأسيس المؤسسة: مشروع سمعة لا مجرد مطبوعة','كيف توثق تاريخ المؤسسة وتبني محتوى ورعايات وهدايا وفعالية حول مناسبة واحدة.','مشاريع المؤسسات','draft','مجلة ذكرى تأسيس المؤسسة','فكرة مجلة الذكرى السنوية للشركات والمؤسسات وكيف تتحول إلى مشروع تسويقي.'),
('flex-vs-banner','فليكس أم بنر؟ اختيار الخامة الصحيحة للإعلان','الفروق العملية في الاستخدام والمتانة والإضاءة والتشطيب.','الطباعة الكبيرة','draft','الفرق بين الفليكس والبنر','مقارنة عملية بين خامات الفليكس والبنر للإعلانات.'),
('product-packaging-checklist','قائمة فحص تغليف المنتج قبل الطباعة','الأبعاد والخامة والقالب والألوان والليبل والباركود والعينة الأولية.','التعبئة والتغليف','draft','تجهيز تغليف المنتج للطباعة','قائمة عملية قبل طباعة علب وتغليف المنتجات.')
